.ds-control-demo{font:400 12px/1.5 "Inter Variable",sans-serif;color:var(--ink,#242424)}.ds-field-control { display: flex; flex-direction: column; gap: 9px; min-width: 0; }
.ds-field-label { color: #6b6b66; font-size: 12px; font-weight: 450; letter-spacing: -.01em; line-height: 18px; }
.ds-control-trigger { width: 100%; min-width: 0; min-height: 38px; justify-content: space-between; padding: 8px 11px; border: 1px solid #e2e2df; border-radius: 8px; background: #fafaf9; color: #363633; box-shadow: inset 0 1px 2px #00000003; font-size: 12px; font-weight: 400; text-align: left; transition: border-color 120ms ease, background-color 120ms ease, box-shadow 120ms ease; }
.ds-control-trigger>span:first-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-control-trigger:hover:not(:disabled) { background: #f5f5f3; border-color: #c6c6c0; }
.ds-control-trigger:active:not(:disabled) { transform: none; }
.ds-control-trigger[data-popup-open], .ds-control-trigger:focus-visible { background: #fff; border-color: #94a9dc; box-shadow: 0 0 0 3px #436bd812; outline: none; }
.ds-control-icon { display: block; flex: 0 0 auto; color: #777772; }
.ds-control-icon.ds-chevron { width: 14px; height: 14px; }
.ds-control-trigger[data-popup-open] .ds-control-icon.ds-chevron { transform: rotate(180deg); }
.ds-control-positioner { z-index: 20; outline: none; }
.ds-select-popup, .ds-calendar-popup { background: #fffffff7; backdrop-filter: blur(16px); border-radius: 12px; color: var(--ink,#242424); box-shadow: 0 8px 32px #00000016, 0 2px 6px #00000008, 0 0 0 1px #0000000b; transform-origin: var(--transform-origin); transition: opacity 120ms cubic-bezier(.23,1,.32,1), transform 120ms cubic-bezier(.23,1,.32,1); }
.ds-select-popup[data-starting-style], .ds-calendar-popup[data-starting-style], .ds-select-popup[data-ending-style], .ds-calendar-popup[data-ending-style] { opacity: 0; transform: translateY(-3px) scale(.98); }
.ds-select-popup { min-width: var(--anchor-width); width: max-content; max-width: calc(100vw - 24px); padding: 5px; }
.ds-select-options { max-height: min(340px, var(--available-height, 340px)); overflow: auto; outline: none; }
.ds-select-option { display: grid; grid-template-columns: 1fr 16px; align-items: center; gap: 16px; padding: 9px 10px; min-height: 36px; border-radius: 7px; font-size: 12px; cursor: default; user-select: none; outline: none; scroll-margin-block: 5px; }
.ds-select-option[data-highlighted] { background: #efefec; }
.ds-select-option[data-selected] { color: #242424; font-weight: 500; }
.ds-select-check .ds-control-icon { color: #436bd8; width: 14px; height: 14px; }
.ds-date-trigger { justify-content: flex-start; color: #71716b; }
.ds-date-trigger.ds-has-date { color: #363633; }
.ds-date-trigger>.ds-control-icon.ds-chevron { margin-left: auto; }
.ds-date-trigger>span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-calendar-popup { width: 286px; max-width: calc(100vw - 24px); padding: 14px; }
.ds-calendar-title { margin: 0 0 12px; padding: 0 3px 12px; border-bottom: 1px solid #eee; color: #6b6b66; font-size: 11px; font-weight: 450; letter-spacing: 0; }
.ds-calendar { --rdp-accent-color: #292928; --rdp-accent-background-color: #f0f1f4; --day-size: 36px; --rdp-day-width: var(--day-size); --rdp-day-height: var(--day-size); --rdp-day_button-width: calc(var(--day-size) - 2px); --rdp-day_button-height: calc(var(--day-size) - 2px); --rdp-day_button-border-radius: 8px; --rdp-selected-border: none; --rdp-nav_button-width: 28px; --rdp-nav_button-height: 28px; --rdp-nav-height: 36px; --rdp-outside-opacity: .45; --rdp-disabled-opacity: .3; font-size: 12px; }
.ds-calendar .ds-rdp-months { justify-content: center; width: 100%; }
.ds-calendar .ds-rdp-month { width: 100%; }
.ds-calendar .ds-rdp-month_caption { height: 36px; margin-bottom: 10px; }
.ds-calendar .ds-rdp-caption_label { font-size: 13px; font-weight: 550; letter-spacing: -.025em; }
.ds-calendar table { border-collapse: collapse; width: 100%; white-space: normal; }
.ds-calendar th, .ds-calendar td { border: 0; padding: 0; text-align: center; background: transparent; }
.ds-calendar thead th { position: static; }
.ds-calendar .ds-rdp-weekday { height: 30px; color: #71716b; font-size: 10px; font-weight: 400; opacity: 1; }
.ds-calendar tbody tr, .ds-calendar tbody tr:hover { background: transparent; cursor: default; }
.ds-calendar button { min-height: 0; padding: 0; gap: 0; background: transparent; border: 0; color: #363633; box-shadow: none; font-size: 12px; font-weight: 400; }
.ds-calendar button:hover:not(:disabled) { background: #eeefeb; }
.ds-calendar button:active:not(:disabled) { transform: none; }
.ds-calendar .ds-rdp-selected { font-size: 12px; font-weight: 500; }
.ds-calendar .ds-rdp-selected .ds-rdp-day_button, .ds-calendar .ds-rdp-selected .ds-rdp-day_button:hover { background: #292928; color: #fff; }
.ds-calendar .ds-rdp-today:not(.ds-rdp-selected) .ds-rdp-day_button { color: #436bd8; font-weight: 650; background: #f0f3fc; }
.ds-calendar .ds-rdp-chevron { width: 15px; height: 15px; fill: #6b6b66; }
.ds-calendar button:disabled { cursor: not-allowed; }
.ds-calendar-footer { display: flex; justify-content: space-between; margin-top: 12px; padding-top: 10px; border-top: 1px solid #eee; }
.ds-calendar-action { padding: 5px 8px; min-height: 30px; background: transparent; color: #63635e; box-shadow: none; font-size: 11px; }
.ds-calendar-action:hover:not(:disabled) { background: #f0f0ed; color: #242424; }
.ds-calendar-action:disabled { cursor: default; }.ds-control-trigger{display:inline-flex;align-items:center;gap:8px;cursor:pointer}.ds-control-trigger:focus-visible,.ds-calendar button:focus-visible,.ds-calendar-action:focus-visible{outline:3px solid #0071e3;outline-offset:3px}.ds-control-trigger:focus-visible{outline:none}.ds-select-popup,.ds-calendar-popup{margin-top:7px}.ds-calendar button{cursor:pointer;border-radius:8px}.ds-calendar-action{border:0;border-radius:9px;cursor:pointer}.ds-calendar-action:disabled{opacity:.48}@media(max-width:600px){.ds-control-trigger{min-height:44px;font-size:13px}.ds-select-option{min-height:44px;font-size:13px}.ds-calendar-popup{width:min(330px,calc(100vw - 24px))}.ds-calendar{--day-size:calc((min(330px,100vw - 24px) - 28px)/7);--rdp-nav_button-width:40px;--rdp-nav_button-height:40px;--rdp-nav-height:44px}.ds-calendar .ds-rdp-month_caption{height:44px}.ds-calendar-action{min-height:40px}.ds-calendar-title{font-size:12px}}@media(prefers-reduced-transparency:reduce){.ds-select-popup,.ds-calendar-popup{background:#fff;backdrop-filter:none}}@media(prefers-contrast:more){.ds-control-trigger{border-color:#62626b}.ds-select-popup,.ds-calendar-popup{background:#fff;outline:1px solid #62626b}}@media(prefers-reduced-motion:reduce){.ds-control-demo *{transition-duration:0ms!important}}

